 @Override public void onCreate(Bundle saved){super.onCreate(saved);TextView v=new TextView(this);v.setText("正在检查隔离号码格式/存储；不读取实际名单、不拨电话。");setContentView(v);new Thread(()->{JSONObject j=new JSONObject();boolean ok=false;try{runChecks();checks+=LocalDraftStoreChecks.run(this);checks+=LocalPlanStoreChecks.run(this);checks+=PilotStoreChecks.run(this);checks+=LocalDraftBatchStoreChecks.run(this);j.put("decision","PASSED");ok=true;}catch(Exception|AssertionError e){try{j.put("decision","FAILED").put("errorCode",e.getMessage()!=null&&e.getMessage().matches("[A-Z_0-9]+")?e.getMessage():"FIXTURE_FAILED");}catch(Exception ignored){}}try{j.put("tests","T661-T666,T670-T671,T677-T681,T686-T690,T692-T703,T706-T708,T721-T725,T732").put("readOnlyFileBytesChanged",readOnlyFileBytesChanged).put("readOnlyChangedOffsets",new org.json.JSONArray(readOnlyChangedOffsets)).put("assertions",checks).put("source","GENERATED_ISOLATED_FIXTURE").put("userIntakeOpened",false).put("actualPhoneCalls",0).put("realCallsEnabled",false);AtomicFile file=new AtomicFile(new File(getFilesDir(),"phone-intake-check.json"));FileOutputStream out=file.startWrite();out.write(j.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));file.finishWrite(out);}catch(Exception ignored){ok=false;}boolean passed=ok;runOnUiThread(()->v.setText(passed?"号码存储隔离检查通过":"号码存储检查未通过，保留数据与报告。"));},"phone-intake-fixture").start();}
